void* apple_arm::dispatch() {
  if( ac_pc >= dec_cache_size){
    cerr << "ArchC: Address out of bounds (pc=0x" << hex << ac_pc << ")." << endl;
    stop();
    longjmp(ac_env, AC_ACTION_STOP);
  }
  ac_instr_counter++;
  unsigned ins_id;
  instr_dec = (DEC_CACHE + (ac_pc / 4));
  if ( !instr_dec->valid ){
    unsigned* ins_cache;
    decode_pc = ac_pc;
    quant = 0;
    ins_cache = (ISA.decoder)->Decode(reinterpret_cast<unsigned char*>(buffer), quant);
    instr_dec->valid = true;
    instr_dec->id = ins_cache ? ins_cache[IDENT]: 0;
    instr_dec->end_rot = IntRoutine[instr_dec->id];
    switch (ISA.instr_format_table[instr_dec->id]) {
      case 1:
        instr_dec->F_Type_DP_Reg.op = ins_cache[1];
        instr_dec->F_Type_DP_Reg.opt = ins_cache[2];
        instr_dec->F_Type_DP_Reg.rm = ins_cache[3];
        instr_dec->F_Type_DP_Reg.subop = ins_cache[4];
        instr_dec->F_Type_DP_Reg.rn = ins_cache[5];
        instr_dec->F_Type_DP_Reg.rd = ins_cache[6];
      break;
      case 2:
        instr_dec->F_Type_DP_Imm.op = ins_cache[1];
        instr_dec->F_Type_DP_Imm.imm14 = ins_cache[7];
        instr_dec->F_Type_DP_Imm.rn = ins_cache[5];
        instr_dec->F_Type_DP_Imm.rd = ins_cache[6];
      break;
      case 3:
        instr_dec->F_Type_LS_Imm.op = ins_cache[1];
        instr_dec->F_Type_LS_Imm.disp = ins_cache[8];
        instr_dec->F_Type_LS_Imm.rn = ins_cache[5];
        instr_dec->F_Type_LS_Imm.rd = ins_cache[6];
      break;
      case 4:
        instr_dec->F_Type_PAC.op = ins_cache[1];
        instr_dec->F_Type_PAC.pac_op = ins_cache[9];
        instr_dec->F_Type_PAC.rn = ins_cache[10];
        instr_dec->F_Type_PAC.subop = ins_cache[11];
        instr_dec->F_Type_PAC.rd = ins_cache[6];
      break;
      case 5:
        instr_dec->F_Type_Branch_Cond.op = ins_cache[1];
        instr_dec->F_Type_Branch_Cond.imm19 = ins_cache[12];
        instr_dec->F_Type_Branch_Cond.o = ins_cache[13];
        instr_dec->F_Type_Branch_Cond.cond = ins_cache[14];
      break;
      case 6:
        instr_dec->F_Type_Branch_Imm.op = ins_cache[1];
        instr_dec->F_Type_Branch_Imm.imm24 = ins_cache[15];
      break;
      case 7:
        instr_dec->F_Type_Halt.op = ins_cache[1];
        instr_dec->F_Type_Halt.pad = ins_cache[16];
      break;
      default:
        cerr << "ArchC Error: Unidentified instruction. " << endl;
        cerr << "PC = " << hex << ac_pc << dec << endl;
        stop();
        longjmp(ac_env, AC_ACTION_STOP);
    }
  }
  ins_id = instr_dec->id;

  return instr_dec->end_rot;
}

